// src/RoleSelection.js
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "./auth";
import axios from "axios";

export default function RoleSelection() {
  const { user, setUser } = useAuth();
  const navigate = useNavigate();
  const [selectedRole, setSelectedRole] = useState(user?.role || "");
  const [subRole, setSubRole] = useState(user?.subRole || "");
  const [customPurpose, setCustomPurpose] = useState(user?.customPurpose || "");

  const handleContinue = async () => {
    if (!selectedRole) {
      alert("Please select a role.");
      return;
    }

    // Update user on frontend
    const updatedUser = { ...user, role: selectedRole, subRole, customPurpose };
    setUser(updatedUser);

    // Optionally update server-side profile
    const token = localStorage.getItem("token");
    if (token) {
      try {
        await axios.put(
          "http://localhost:5000/api/profile/role",
          { role: selectedRole, subRole, customPurpose },
          { headers: { Authorization: `Bearer ${token}` } }
        );
      } catch (err) {
        // ignore or show warning
        console.warn("Could not update role on server:", err?.response?.data || err);
      }
    }

    navigate("/dashboard");
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-6">
      <div className="max-w-xl w-full bg-white rounded-2xl shadow p-6">
        <h3 className="text-xl font-semibold mb-4">Select your role</h3>

        <div className="flex gap-3 mb-4">
          <button
            onClick={() => setSelectedRole("student")}
            className={`px-4 py-2 rounded-lg border ${selectedRole === "student" ? "bg-indigo-600 text-white" : ""}`}
          >
            Student
          </button>
          <button
            onClick={() => setSelectedRole("teacher")}
            className={`px-4 py-2 rounded-lg border ${selectedRole === "teacher" ? "bg-indigo-600 text-white" : ""}`}
          >
            Teacher
          </button>
          <button
            onClick={() => setSelectedRole("other")}
            className={`px-4 py-2 rounded-lg border ${selectedRole === "other" ? "bg-indigo-600 text-white" : ""}`}
          >
            Other
          </button>
        </div>

        <input
          name="subRole"
          placeholder="Sub role (optional)"
          value={subRole}
          onChange={(e) => setSubRole(e.target.value)}
          className="w-full p-3 mb-3 border rounded-lg"
        />

        <input
          name="customPurpose"
          placeholder="Custom purpose (optional)"
          value={customPurpose}
          onChange={(e) => setCustomPurpose(e.target.value)}
          className="w-full p-3 mb-3 border rounded-lg"
        />

        <div className="flex justify-end gap-3">
          <button onClick={() => navigate(-1)} className="px-4 py-2 rounded-lg border">Back</button>
          <button onClick={handleContinue} className="px-4 py-2 rounded-lg bg-indigo-600 text-white">Continue</button>
        </div>
      </div>
    </div>
  );
}
